import org.apache.commons.lang3.time.DurationFormatUtils;
import java.util.TimeZone;
import java.util.Calendar;

public class Probe {
    public static void main(String[] args) throws Exception {
        System.out.println("durHMS(0)=" + DurationFormatUtils.formatDurationHMS(0));
        System.out.println("durHMS(3661001)=" + DurationFormatUtils.formatDurationHMS(3661001));
        System.out.println("durISO(0)=" + DurationFormatUtils.formatDurationISO(0));
        System.out.println("durISO(3661001)=" + DurationFormatUtils.formatDurationISO(3661001));
        System.out.println("durWords(0,false,false)=" + DurationFormatUtils.formatDurationWords(0, false, false));
        System.out.println("durWords(0,true,true)=" + DurationFormatUtils.formatDurationWords(0, true, true));
        System.out.println("durWords(1000,false,false)=" + DurationFormatUtils.formatDurationWords(1000, false, false));
        System.out.println("durWords(86400000+3600000+60000+1000,false,false)=" + DurationFormatUtils.formatDurationWords(86400000L+3600000+60000+1000, false, false));
        System.out.println("durWords(86400000,true,true)=" + DurationFormatUtils.formatDurationWords(86400000L, true, true));
        System.out.println("durWords(60000,true,true)=" + DurationFormatUtils.formatDurationWords(60000, true, true));
        System.out.println("durWords(3600000,true,true)=" + DurationFormatUtils.formatDurationWords(3600000, true, true));
        System.out.println("fmtDuration(0,'d:H:m:s')=" + DurationFormatUtils.formatDuration(0, "d:H:m:s"));
        System.out.println("fmtDuration(90061000,'d:H:m:s')=" + DurationFormatUtils.formatDuration(90061000L, "d:H:m:s"));
        System.out.println("fmtDuration(90061000,'d:H:m:s',false)=" + DurationFormatUtils.formatDuration(90061000L, "d:H:m:s", false));
        System.out.println("fmtDuration literal S (long format): " + DurationFormatUtils.formatDuration(90061023L, "d' days 'H' hours 'm' minutes 's.S' seconds'"));
        try {
            DurationFormatUtils.formatDuration(-1, "d:H:m:s");
            System.out.println("NO EXCEPTION for negative");
        } catch (IllegalArgumentException e) {
            System.out.println("negative -> IAE: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatPeriod(10, 5, "d");
            System.out.println("NO EXCEPTION for start>end");
        } catch (IllegalArgumentException e) {
            System.out.println("start>end -> IAE: " + e.getMessage());
        }
        TimeZone gmt = TimeZone.getTimeZone("GMT");
        System.out.println("formatPeriod same millis = " + DurationFormatUtils.formatPeriod(1000, 1000, "d:H:m:s", true, gmt));

        Calendar c1 = Calendar.getInstance(gmt);
        c1.clear();
        c1.set(2000,0,15); // Jan 15 2000
        Calendar c2 = Calendar.getInstance(gmt);
        c2.clear();
        c2.set(2000,2,10); // Mar 10 2000
        System.out.println("period Jan15->Mar10 y M d = " + DurationFormatUtils.formatPeriod(c1.getTimeInMillis(), c2.getTimeInMillis(), "M'M'd'D'", true, gmt));
        System.out.println("formatPeriodISO sameday = " + DurationFormatUtils.formatPeriodISO(c1.getTimeInMillis(), c2.getTimeInMillis()));

        // optional token examples from javadoc
        System.out.println("opt1 day=" + DurationFormatUtils.formatDuration(86400000L, "d'd'[H'h'm'm']s's'"));
        System.out.println("opt1 hour=" + DurationFormatUtils.formatDuration(3600000L, "d'd'[H'h'm'm']s's'"));
        System.out.println("opt1 zero=" + DurationFormatUtils.formatDuration(0L, "d'd'[H'h'm'm']s's'"));

        System.out.println("opt2 day=" + DurationFormatUtils.formatDuration(86400000L, "[d'd'H'h'm'm']s's'"));
        System.out.println("opt2 hour=" + DurationFormatUtils.formatDuration(3600000L, "[d'd'H'h'm'm']s's'"));
        System.out.println("opt2 zero=" + DurationFormatUtils.formatDuration(0L, "[d'd'H'h'm'm']s's'"));

        System.out.println("opt3 day=" + DurationFormatUtils.formatDuration(86400000L, "[d'd'H'h'm'm's's']"));
        System.out.println("opt3 zero=" + DurationFormatUtils.formatDuration(0L, "[d'd'H'h'm'm's's']"));

        System.out.println("opt4 day=" + DurationFormatUtils.formatDuration(86400000L, "['{'d'}']HH':'mm"));
        System.out.println("opt4 hour=" + DurationFormatUtils.formatDuration(3600000L, "['{'d'}']HH':'mm"));
        System.out.println("opt4 zero=" + DurationFormatUtils.formatDuration(0L, "['{'d'}']HH':'mm"));

        System.out.println("opt5 bracket d/H/m/s single no pad=" + DurationFormatUtils.formatDuration(86400000L+3600000+60000+1000, "[dHms]"));
        System.out.println("opt5 zero=" + DurationFormatUtils.formatDuration(0L, "[dHms]"));

        try {
            DurationFormatUtils.formatDuration(0, "[d[H]]");
            System.out.println("no exception nested optional");
        } catch (IllegalArgumentException e) {
            System.out.println("nested optional -> IAE: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "d]");
            System.out.println("no exception unopened close");
        } catch (IllegalArgumentException e) {
            System.out.println("unopened close -> IAE: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "[d");
            System.out.println("no exception unmatched optional");
        } catch (IllegalArgumentException e) {
            System.out.println("unmatched optional -> IAE: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "d'abc");
            System.out.println("no exception unmatched quote");
        } catch (IllegalArgumentException e) {
            System.out.println("unmatched quote -> IAE: " + e.getMessage());
        }
        System.out.println("literal quote: " + DurationFormatUtils.formatDuration(0, "d''d"));
        System.out.println("S only ms=" + DurationFormatUtils.formatDuration(5, "S"));
        System.out.println("S only ms padded 5=" + DurationFormatUtils.formatDuration(5, "SSSSS"));
        System.out.println("s.SSS with secs=" + DurationFormatUtils.formatDuration(1005, "s.SSS"));
        System.out.println("s.S no pad, secs=1 ms=5 ->" + DurationFormatUtils.formatDuration(1005, "s.S", false));
    }
}
