package org.apache.commons.lang3.time;

public class Probe2 {
    public static void main(String[] args) throws Exception {
        DurationFormatUtils.Token[] t1 = DurationFormatUtils.lexx("d'd'H'h'm'm's's'");
        StringBuilder sb = new StringBuilder();
        for (DurationFormatUtils.Token t : t1) sb.append(t.toString());
        System.out.println("lexx1 size=" + t1.length + " rejoined=" + sb);

        DurationFormatUtils.Token[] t2 = DurationFormatUtils.lexx("yyyyyy");
        System.out.println("lexx yyyyyy size=" + t2.length + " count=" + t2[0].getCount() + " value=" + t2[0].getValue());

        DurationFormatUtils.Token[] t3 = DurationFormatUtils.lexx("abc");
        System.out.println("lexx abc size=" + t3.length + " tostring=" + t3[0].toString());

        boolean hasD = DurationFormatUtils.Token.containsTokenWithValue(t1, DurationFormatUtils.d);
        boolean hasY = DurationFormatUtils.Token.containsTokenWithValue(t1, DurationFormatUtils.y);
        System.out.println("hasD=" + hasD + " hasY=" + hasY);

        DurationFormatUtils.Token tokA = new DurationFormatUtils.Token(DurationFormatUtils.d, false, -1);
        DurationFormatUtils.Token tokB = new DurationFormatUtils.Token(DurationFormatUtils.d, false, -1);
        tokB.increment();
        System.out.println("tokA.equals(tokB)=" + tokA.equals(tokB) + " tokA.count=" + tokA.getCount());
        tokA.increment();
        System.out.println("after tokA.increment tokA.equals(tokB)=" + tokA.equals(tokB));
        System.out.println("tokA.equals(\"notatoken\")=" + tokA.equals("notatoken"));
        System.out.println("tokA.hashCode()==d.hashCode() -> " + (tokA.hashCode() == DurationFormatUtils.d.hashCode()));

        try {
            DurationFormatUtils.lexx("'");
            System.out.println("single quote no exception");
        } catch (IllegalArgumentException e) {
            System.out.println("single quote -> IAE: " + e.getMessage());
        }

        try {
            new DurationFormatUtils.Token(null, false, -1);
            System.out.println("null token no exception");
        } catch (NullPointerException e) {
            System.out.println("null token -> NPE: " + e.getMessage());
        }

        String formatted = DurationFormatUtils.format(t1, 0, 0, 1, 2, 3, 4, 0, true);
        System.out.println("direct format call = " + formatted);
    }
}
